import importlib.util, importlib.machinery, random, json, copy, math
loader = importlib.machinery.SourceFileLoader("runmod", "/app/submit/run")
spec = importlib.util.spec_from_loader("runmod", loader)
R = importlib.util.module_from_spec(spec); loader.exec_module(R)
FULL=(1<<128)-1
def trunc(v,b):
    if b<=0: return 0
    if b>=128: return v
    return v & (FULL ^ ((1<<(128-b))-1))
def match(a,v,l):
    if l==0: return True
    s=128-l
    return (a>>s)==(v>>s)
def brute_lpm(fib,a):
    bh=None; bl=-1
    for (v,l,h) in fib:
        if l>bl and match(a,v,l):
            bl=l; bh=h
    if bh is None: return (None,None)
    return (bh,bl)
def rand_fib(rng,nmax=10):
    fib=[]; seen=set()
    for _ in range(rng.randint(0,nmax)):
        l=rng.choice([0,1,8,16,32,48,64,96,100,127,128,rng.randint(0,128)])
        v=trunc(rng.getrandbits(128),l)
        if (v,l) in seen: continue
        seen.add((v,l)); fib.append((v,l,rng.randint(0,65535)))
    return fib
rng=random.Random(99)
issues=0
for trial in range(200):
    fib=rand_fib(rng)
    S=rng.randint(4,8)
    base=(128+S-1)//S
    ms=rng.randint(base, min(32,base+8))
    caps=[rng.randint(1000,100000) for _ in range(S)]
    req={"op":"compile","fib":[{"prefix":R.fmt(v,l),"hop":h} for (v,l,h) in fib],
         "capacities":caps,"max_stride":ms}
    img=R.handle_compile(req)
    if img["status"]!="ok":
        # maybe infeasible; skip
        continue
    # round-trip validate
    addrs=[rng.getrandbits(128) for _ in range(20)]
    # include some prefix addresses
    for (v,l,h) in fib[:5]:
        addrs.append(v)
    req2={"op":"lookup","image":copy.deepcopy(img),"addresses":[R.fmt(a) for a in addrs]}
    try:
        res=R.handle_lookup(req2)
    except R.Invalid:
        print("VALID IMAGE REJECTED",trial); issues+=1; continue
    if res["status"]!="ok":
        print("lookup not ok",trial); issues+=1; continue
    for a,ans in zip(addrs,res["answers"]):
        bh,bl=brute_lpm(fib,a)
        exp={"hop":bh,"prefix_length":bl}
        if ans!=exp:
            print("LPM MISMATCH",trial,R.fmt(a),ans,exp,fib); issues+=1; break
print("lookup tests done issues",issues)
PYEOF
